# Generated by cmd/release-formula of cmdai-hq/humanload-collector at each release; do not edit by hand.
class Humanload < Formula
  desc "Local counts of the work of supervising coding agents"
  homepage "https://humanload.dev"
  license :cannot_represent

  depends_on macos: :ventura

  # brew audit refuses url and sha256 inside on_arm / on_intel: an explicit condition is the accepted form.
  if Hardware::CPU.arm?
    url "https://github.com/cmdai-hq/homebrew-tap/releases/download/v0.9.0/humanload_0.9.0_darwin_arm64.tar.gz"
    sha256 "5143a29f234e15deb6daa1d525e9d8b9133f688fba804300af70a782931591e2"
  else
    url "https://github.com/cmdai-hq/homebrew-tap/releases/download/v0.9.0/humanload_0.9.0_darwin_amd64.tar.gz"
    sha256 "5d40f31064b2a46eea6deabe6e7e5fc0dfb901191c848864d4bc6065bba6eb63"
  end

  def install
    bin.install "humanload"
  end

  def caveats
    <<~EOS
      Set Humanload up, then pair this Mac with your account:
        humanload setup
        humanload login

      Updates come only through brew upgrade humanload.

      Run humanload uninstall before brew uninstall humanload: it removes the
      Claude Code hooks, the two LaunchAgents and the Keychain key, which
      Homebrew cannot remove.

      Between 19:00 and 23:30, an "Evening Note" dialog may ask how much energy
      you have left (1 to 5), and the next morning for a forgotten evening.
      The note stays on this Mac unless you turn on its sync. Cancel closes it
      for the day. To stop it until your next login or humanload setup:
        launchctl bootout gui/$(id -u)/eu.humanload.note
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/humanload version")
  end
end
